import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"AI Agents & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents.md","filePath":"ai/agents.md"}`),a={name:`ai/agents.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="ai-agents-workflows" tabindex="-1">AI Agents &amp; Workflows <a class="header-anchor" href="#ai-agents-workflows" aria-label="Permalink to &quot;AI Agents &amp; Workflows&quot;">​</a></h1><p>TechyNews development is deeply integrated with autonomous AI agents. These agents follow strict rules and workflows defined in the <code>.agents</code> directory to maintain codebase stability, UI consistency, and engineering standards.</p><h2 id="mandatory-senior-engineering-workflow" tabindex="-1">Mandatory Senior Engineering Workflow <a class="header-anchor" href="#mandatory-senior-engineering-workflow" aria-label="Permalink to &quot;Mandatory Senior Engineering Workflow&quot;">​</a></h2><p>All AI agents working on this repository must adhere to a strict 3-phase workflow for every task involving code changes:</p><h3 id="phase-1-analysis-investigation" tabindex="-1">Phase 1: Analysis / Investigation <a class="header-anchor" href="#phase-1-analysis-investigation" aria-label="Permalink to &quot;Phase 1: Analysis / Investigation&quot;">​</a></h3><ul><li>Understand the root cause before writing code.</li><li>Trace data flow end-to-end and check server logs.</li><li>Identify all affected files and endpoints.</li><li><strong>Worktree Isolation:</strong> Always use a branched or shared workspace (<code>git worktree add</code>) to isolate changes. Never work directly on the main branch.</li></ul><h3 id="phase-2-implementation-testing-qa" tabindex="-1">Phase 2: Implementation + Testing / QA <a class="header-anchor" href="#phase-2-implementation-testing-qa" aria-label="Permalink to &quot;Phase 2: Implementation + Testing / QA&quot;">​</a></h3><ul><li>Implement fixes or features in focused chunks.</li><li><strong>Backend:</strong> Run <code>php artisan test</code> and verify endpoint responses.</li><li><strong>Frontend:</strong> Run <code>npm run build</code> to ensure zero compilation errors.</li><li><strong>E2E Tests:</strong> Execute Playwright tests (<code>npx playwright test</code>).</li><li><strong>Integration:</strong> Verify the live endpoint works locally.</li><li><em>Rule:</em> If any test fails, do not deploy. Fix the issue first.</li></ul><h3 id="phase-3-deploy-verify" tabindex="-1">Phase 3: Deploy + Verify <a class="header-anchor" href="#phase-3-deploy-verify" aria-label="Permalink to &quot;Phase 3: Deploy + Verify&quot;">​</a></h3><ul><li>Deploy only after all tests in Phase 2 pass.</li><li>Generate PR descriptions using the internal <code>techy-pr-builder</code> skill.</li><li>Run a smoke test on production post-deploy.</li></ul><h2 id="error-handling-philosophy" tabindex="-1">Error Handling Philosophy <a class="header-anchor" href="#error-handling-philosophy" aria-label="Permalink to &quot;Error Handling Philosophy&quot;">​</a></h2><p><strong>Fail Fast — No Silent Error Swallowing</strong></p><ul><li>All backend errors must be logged via <code>Log::error()</code> with context.</li><li>Frontend errors must display meaningful feedback (e.g., <code>toast.error()</code>) rather than generic messages, while logging the real cause.</li></ul><h2 id="standardized-workflows" tabindex="-1">Standardized Workflows <a class="header-anchor" href="#standardized-workflows" aria-label="Permalink to &quot;Standardized Workflows&quot;">​</a></h2><p>Agents refer to specific markdown files in <code>.agents/workflows/</code> for common tasks:</p><ul><li><strong><code>/generate-news</code></strong>: Steps to generate a new AI-powered article.</li><li><strong><code>/deploy</code></strong>: Procedures for pushing changes to the production server via rsync and SSH.</li><li><strong><code>/fix-content</code></strong>: Instructions on how article content is stored, rendered, and how to fix encoding issues.</li><li><strong><code>/feature-to-pr</code></strong>: The process of taking a feature from implementation to a Pull Request.</li></ul><h2 id="ai-activity-documentation" tabindex="-1">AI Activity Documentation <a class="header-anchor" href="#ai-activity-documentation" aria-label="Permalink to &quot;AI Activity Documentation&quot;">​</a></h2><p>Agents are required to document all significant actions in <code>docs/AI_ACTIVITY.md</code>. This maintains a clear audit trail of AI-driven changes, detailing what was modified, why, what tests were run, and the results.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};